MAIN=MAIN.replace('WriteAt<std::int32_t>(grids[1],416,19);','WriteAt<std::int32_t>(grids[1],416,0);',1).replace('Door.Slot==19,','Door.Slot==0,',1)
# Spawns uses the production API600 container guard as well as API500 fields.
# Keep the fixed-NRO fingerprints in this synthetic module; never relax guards.
CONTAINER_GUARDS = '''
const unsigned char guardSpawnList[]={0xfd,0x43,0x02,0x91,0xfc,0x6f,0x0a,0xa9,0xfa,0x67,0x0b,0xa9,0xf8,0x5f,0x0c,0xa9};
const unsigned char guardSpawnEntry[]={0xf8,0x5f,0x03,0xa9,0xf6,0x57,0x04,0xa9,0xf4,0x4f,0x05,0xa9,0xf4,0x03,0x00,0xaa};
std::memcpy(g_ModuleBytes.data()+0x48f490,guardSpawnList,16);
std::memcpy(g_ModuleBytes.data()+0x495248,guardSpawnEntry,16);
LuaRuntime::SetEngineModuleBase(g_EngineBase);'''

def run_world(args=(),main=MAIN):
 main=main.replace('LuaRuntime::SetEngineModuleBase(g_EngineBase);',CONTAINER_GUARDS,1)
 prefix=fixture.HARNESS[:fixture.HARNESS.index('int main(')]
 prefix=re.sub(r'namespace GameFileReader \{\nTextReadResult[\s\S]*?\n\}\n\}', '',prefix,count=1)
 for name,func,enum in [('ReadCurrentGameRoom','Api500WorldRoom','RoomUnreadable'),('ReadCurrentGameItemPool','Api500WorldPool','GameUnreadable')]:
  pattern=r'GameRoomObservation '+name+r'\(uintptr_t, void\*\*\) \{\n    return GameRoomObservation::'+enum+r';\n\}' if name=='ReadCurrentGameRoom'else r'GameItemPoolObservation '+name+r'\(uintptr_t, void\*\*\) \{\n    return GameItemPoolObservation::'+enum+r';\n\}'
  obs='GameRoomObservation'if name=='ReadCurrentGameRoom'else'GameItemPoolObservation'
  replacement='void* '+func+'();\n'+obs+' '+name+'(uintptr_t,void** p){*p='+func+'();return '+obs+'::Success;}'
  prefix,n=re.subn(pattern,lambda _:replacement,prefix,count=1);assert n==1,name
 with tempfile.TemporaryDirectory(prefix='api500-world-')as d:
  binary=build_lua_harness(source_root=fixture.SOURCE,workdir=Path(d),harness_source=prefix+main)
  return subprocess.run([str(binary),*args],capture_output=True,text=True)
class WorldConsumer(unittest.TestCase):
 def test_grid_vardata_writes_share_the_native_save_state(self):
  marker='const char*script=R"lua(';start=MAIN.index(marker)+len(marker);end=MAIN.index(')lua";',start)
  script=r'''
local room=Game():GetRoom();local g=room:GetGridEntity(1);local d=room:GetGridEntity(2):ToDoor()
g.VarData=1;assert(g.VarData==1 and g:GetSaveState().VarData==1)
g.VarData=4294967297;assert(g.VarData==1)
g.VarData=1.0;assert(g:GetSaveState().VarData==1)
g.VarData=-1;assert(g.VarData==-1 and g:GetSaveState().VarData==-1)
d.VarData=1;assert(d.VarData==1 and d:GetSaveState().VarData==1)
assert(not pcall(function()g.VarData=1.5 end));assert(not pcall(function()g.VarData={}end))
assert(not pcall(function()g.VarData=nil end))
'''
  main=MAIN[:start]+script+MAIN[end:]
  before='if(LuaRuntime::InitializeFromBuffer(script,std::strlen(script),"@api500-world.lua")'
  setup='auto varDataExpected=grids;WriteAt<std::int32_t>(varDataExpected[0],0x1c,-1);WriteAt<std::int32_t>(varDataExpected[1],0x1c,1);\n'
  assert before in main;main=main.replace(before,setup+before,1)
  where=main.rfind('return 0;}');assert where>=0
  main=main[:where]+'assert(grids==varDataExpected);'+main[where:]
  r=run_world(('vardata',),main=main);self.assertEqual(r.returncode,0,r.stdout+r.stderr)
 def test_new_fields_and_pill(self):
  r=run_world();self.assertEqual(r.returncode,0,r.stdout+r.stderr)
 def test_original_grid_variant(self):
  r=run_world(('variant',));self.assertEqual(r.returncode,0,r.stdout+r.stderr)
